(function () {
"use strict";

// --- LÓGICA DO CRONÔMETRO ---
let timerInterval = null;
let seconds = 0;

function startTimer() {
if (!timerInterval) {
timerInterval = setInterval(() => {
seconds++;
const m = Math.floor(seconds / 60).toString().padStart(2, '0');
const s = (seconds % 60).toString().padStart(2, '0');
document.getElementById('crono-timer').textContent = `${m}:${s}`;
}, 1000);
}
}

// --- ESTRUTURA DE DADOS DOS CRITÉRIOS DE SILVERMAN (MÁX 2 PONTOS CADA) ---
const ITENS_SILVERMAN = [
{
id: "mov",
label: "1. Ruchy Klatki Piersiowej i Brzucha",
max: 2,
desc: "Synchronizacja między klatką piersiową a brzuchem.",
