{ val: 0, text: "Zsynchronizowane (0)" },
{ val: 1, text: "Klatka nieruchoma (1)" },
{ val: 2, text: "Huśtawka (2)" }
],
},
{
id: "tiragem",
label: "2. Wciąganie Międzyżebrowe",
max: 2,
desc: "Wciąganie mięśni między żebrami.",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "Brak (0)" },
{ val: 1, text: "Łagodne (1)" },
{ val: 2, text: "Wyraźne (2)" }
],
},
{
id: "retracao",
label: "3. Retrakcja Wyrostka Mieczykowatego",
max: 2,
desc: "Zapadanie się okolicy wyrostka mieczykowatego.",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "Brak (0)" },
{ val: 1, text: "Łagodne (1)" },
{ val: 2, text: "Wyraźne (2)" }
],
},
{
id: "batimento",
label: "4. Skrzydełkowanie nosa",
max: 2,
desc: "Rozszerzanie nozdrzy podczas wdechu.",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "Brak (0)" },
{ val: 1, text: "Łagodne (1)" },
{ val: 2, text: "Wyraźny (2)" }
],
},
{
id: "gemido",
label: "5. Jęk wydechowy",
max: 2,
desc: "Dźwięk wydawany podczas wydechu.",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "Brak (0)" },
{ val: 1, text: "Słyszalny przez stetoskop (1)" },
{ val: 2, text: "Słyszalny bez stetoskopu (2)" }
],
}
];

// --- RENDERIZAÇÃO DOS CARDS (GRID) ---
function renderizarItensSilverman() {
const container = document.getElementById("silvForm");
container.innerHTML = "";

ITENS_SILVERMAN.forEach((item) => {
let optsHtml = "";
item.opts.forEach((op) => {
optsHtml += `<option value="${op.val}" ${op.val === "" ? "disabled selected" : ""}>${op.text}</option>`;
});

const div = document.createElement("div");
div.className = "item-card";
div.id = `card_${item.id}`;
div.innerHTML = `
<div class="flex items-center justify-between mb-2">
<label for="${item.id}" class="text-[13px] font-bold text-slate-800">${item.label}</label>
<span id="badge_${item.id}" class="item-badge">--/2</span>
</div>
<p class="text-[11px] text-slate-500 mb-3 leading-snug h-8">${item.desc}</p>
<select id="${item.id}" class="item-select">${optsHtml}</select>
<div class="mini-bar-wrap">
<div id="bar_${item.id}" class="mini-bar-fill" style="width: 0%;"></div>
</div>
`;
container.appendChild(div);

const el = document.getElementById(item.id);
// Listener para atualizar card individual
el.addEventListener("change", () => {
document.getElementById(`card_${item.id}`).classList.remove("error");
document.getElementById("msgValidacaoErro").style.display = "none";
atualizarCardIndividual(item.id);
});

el.addEventListener('change', startTimer, {once: true});

// Evitar scroll acidental
el.addEventListener("wheel", function(e) { e.preventDefault(); this.blur(); });
});
}

// --- ATUALIZAR STATUS DE UM CARD ESPECÍFICO ---
function atualizarCardIndividual(id) {
const select = document.getElementById(id);
const valStr = select.value;
if (valStr === "") return;
const val = parseInt(valStr);
const max = 2;
// Barra sempre visível: mínimo 10% para mostrar a cor
const pct = Math.max((val / max) * 100, 10);

const badge = document.getElementById(`badge_${id}`);
const bar = document.getElementById(`bar_${id}`);

badge.textContent = `${val}/${max}`;
bar.style.width = `${pct}%`;

// Cores baseadas na gravidade (0 é verde, 2 é vermelho)
let cor = "transparent";
if (val === 0) cor = "#16a34a"; // Verde
else if (val === 1) cor = "#f97316"; // Laranja
else if (val === 2) cor = "#e11d48"; // Vermelho

bar.style.backgroundColor = cor;

// Badge também muda de cor conforme escore
badge.style.backgroundColor = cor === "transparent" ? "" : `${cor}15`;
badge.style.color = cor === "transparent" ? "" : cor;
badge.style.borderColor = cor === "transparent" ? "" : `${cor}30`;

atualizarBarraGlobal();
}

// --- BARRA FLUTUANTE GLOBAL E CONTADOR ---
function atualizarBarraGlobal() {
let preenchidos = 0;
ITENS_SILVERMAN.forEach((i) => {
if (document.getElementById(i.id).value !== "") preenchidos++;
});

const pctGlobal = (preenchidos / 5) * 100;
document.getElementById("progress-bar-global").style.width = `${pctGlobal}%`;
document.getElementById("contadorPreenchidos").textContent = `${preenchidos}/5`;
}

// --- LÓGICA DADOS DO PACIENTE (TOGGLE) ---
document.getElementById("btnToggleDados").addEventListener("click", function () {
const body = document.getElementById("dadosBody");
const chevron = document.getElementById("dadosChevron");
const subtitle = document.getElementById("dadosSubtitle");

if (body.classList.contains("open")) {
body.classList.remove("open");
chevron.style.transform = "rotate(0deg)";
subtitle.textContent = "Wypełnij do dokumentacji medycznej/raportu PDF";
this.style.background = "white";
} else {
body.classList.add("open");
chevron.style.transform = "rotate(180deg)";
subtitle.textContent = "Ukryj panel";
this.style.background = "#EFF6FF";
}
});
document.getElementById("pacData").value = new Date().toISOString().split("T")[0];

// --- CÁLCULO E RESULTADO ---
const resultadoSection = document.getElementById("resultado-section");

function calcular() {
let incompleto = false;
let somaTotal = 0;
let dominiosValores = [];
let diagnosticosKeywords = [];
let primeiroErro = null;

ITENS_SILVERMAN.forEach((item) => {
const selectVal = document.getElementById(item.id).value;
if (selectVal === "") {
incompleto = true;
document.getElementById(`card_${item.id}`).classList.add("error");
if(!primeiroErro) primeiroErro = document.getElementById(`card_${item.id}`);
dominiosValores.push({ nome: item.label, obtido: 0, max: item.max });
} else {
document.getElementById(`card_${item.id}`).classList.remove("error");
const val = parseInt(selectVal);
somaTotal += val;
dominiosValores.push({ nome: item.label, obtido: val, max: item.max });

// Alimentando palavras-chave para o NANDA se a pontuação for crítica
if (val > 0) diagnosticosKeywords.push("respiração", "ventilação", "gases", "oxigenação", "desobstrução");
}
});

if (incompleto) {
const msgErro = document.getElementById("msgValidacaoErro");
msgErro.style.display = "block";
if (primeiroErro) {
primeiroErro.scrollIntoView({ behavior: 'smooth', block: 'center' });
}
return;
}

document.getElementById("msgValidacaoErro").style.display = "none";
clearInterval(timerInterval);

// Determinar Classificação
let classe = "",
bgPill = "",
recomendacao = "";

if (somaTotal === 0) {
classe = "Bez trudności oddechowych";
bgPill = "#16a34a"; // Verde
recomendacao = "Noworodek w dobrym stanie oddechowym. Rutynowa opieka.";
} 
else if (somaTotal >= 1 && somaTotal <= 3) {
classe = "Łagodna niewydolność oddechowa";
bgPill = "#eab308"; // Amarelo
recomendacao = "Początkowe objawy trudności oddechowych. Wymaga ciągłej obserwacji i ewentualnego lekkiego wsparcia tlenowego.";
} 
else if (somaTotal >= 4 && somaTotal <= 7) {
classe = "Umiarkowana niewydolność oddechowa";
bgPill = "#ea580c"; // Laranja
recomendacao = "Zaburzenia oddechowe. Konieczna interwencja (CPAP lub kontrolowana tlenoterapia) w celu stabilizacji klinicznej.";
} 
else if (somaTotal >= 8) {
classe = "Ciężka niewydolność oddechowa";
bgPill = "#e11d48"; // Vermelho
recomendacao = "Zbliżająca się niewydolność oddechowa. Rozważ zaawansowane wsparcie wentylacyjne (wentylacja mechaniczna) i przyjęcie na oddział intensywnej terapii noworodków.";
} 

// Exibir no Hero Card
document.getElementById("scoreValor").textContent = somaTotal;
const pill = document.getElementById("statusPill");
pill.textContent = classe;
pill.style.backgroundColor = bgPill;

// Destacar card correspondente no Sidebar
const scpIds = ["scp-zero", "scp-leve", "scp-moderado", "scp-grave"];
scpIds.forEach(id => {
const el = document.getElementById(id);
if (el) {
el.style.transform = "scale(1)";
el.style.boxShadow = "";
el.classList.remove("scp-highlight");
}
});

let scpAlvo = null;
if (somaTotal === 0) scpAlvo = document.getElementById("scp-zero");
else if (somaTotal >= 1 && somaTotal <= 3) scpAlvo = document.getElementById("scp-leve");
else if (somaTotal >= 4 && somaTotal <= 7) scpAlvo = document.getElementById("scp-moderado");
else if (somaTotal >= 8) scpAlvo = document.getElementById("scp-grave");

if (scpAlvo) {
scpAlvo.style.transform = "scale(1.03)";
scpAlvo.style.boxShadow = "0 8px 25px rgba(0,0,0,0.25)";
scpAlvo.classList.add("scp-highlight");
}

document.getElementById("resultadoMensagem").innerHTML = `Noworodek uzyskał <strong>${somaTotal} punktów</strong> na maksymalnie 10.<br><br><strong>Zalecenia:</strong> ${recomendacao}`;

// Gerar Tabela de Detalhamento
const tbody = document.getElementById("tabelaDominios");
tbody.innerHTML = "";
dominiosValores.forEach((dom) => {
const pct = Math.round((dom.obtido / dom.max) * 100);

let cor = "transparent";
if (dom.obtido === 0) cor = "#16a34a";
else if (dom.obtido === 1) cor = "#f97316";
else if (dom.obtido === 2) cor = "#e11d48";

const tr = document.createElement("tr");
tr.innerHTML = `
<td class="font-bold text-slate-700">${dom.nome}</td>
<td class="text-center font-black" style="color: ${cor}">${dom.obtido}</td>
<td class="text-center text-slate-400">${dom.max}</td>
<td>
<div class="flex items-center gap-3">
<div class="flex-1 h-[6px] bg-slate-200 rounded-full overflow-hidden">
<div style="width: ${pct}%; background-color: ${cor};" class="h-full rounded-full"></div>
</div>
<span class="text-[11px] font-bold" style="color: ${cor}">${pct}%</span>
</div>
</td>
`;
tbody.appendChild(tr);
});
document.getElementById("totalObtidoTd").textContent = somaTotal;
document.getElementById("totalObtidoTd").style.color = bgPill;

// Mostrar Seção
resultadoSection.classList.add("visible");
resultadoSection.style.display = "block";
setTimeout(() => {
resultadoSection.scrollIntoView({ behavior: "smooth", block: "start" });
}, 100);

// Se a pontuação for 0, podemos adicionar "conforto" nas keywords para sugerir bem-estar
if (somaTotal === 0) diagnosticosKeywords = ["conforto"];

// Chamar NANDA
chamarNanda(diagnosticosKeywords);
}

async function chamarNanda(keywords) {
const lista = document.getElementById("lista-nanda");
lista.innerHTML = '<li class="text-sm text-slate-500 text-center py-4"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" class="fa-spin mr-2 inline-block" fill="currentColor" width="1em" height="1em" aria-hidden="true"><path d="M304 48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zm0 416a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM48 304a48 48 0 1 0 0-96 48 48 0 1 0 0 96zm464-48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM142.9 437A48 48 0 1 0 75 369.1 48 48 0 1 0 142.9 437zm0-294.2A48 48 0 1 0 75 75a48 48 0 1 0 67.9 67.9zM369.1 437A48 48 0 1 0 437 369.1 48 48 0 1 0 369.1 437z"/></svg> Konsultacja z bazą danych NANDA-I...</li>';

try {
const response = await fetch("/banco_nanda.json");
if (!response.ok) throw new Error("Błąd pobierania");
const banco = await response.json();

const pontuados = banco
.map((diag) => {
let matchScore = 0;
const texto = (diag.diagnostico + " " + diag.definicao).toLowerCase();
keywords.forEach((kw) => {
if (texto.includes(kw.toLowerCase())) matchScore++;
});
return { ...diag, matchScore };
})
.filter((d) => d.matchScore > 0);

pontuados.sort((a, b) => b.matchScore - a.matchScore);

// Dedup: evitar diagnósticos com temas repetidos
const prefixosIgnorar = ["ryzyko", "gotowość do", "zespół", "tendencja do", "gotowość do", "ryzyko"];
const temasUsados = new Set();
const topDiversos = [];

function extrairTema(titulo) {
let t = titulo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
// Remove prefixos comuns
for (const p of prefixosIgnorar) {
if (t.startsWith(p)) { t = t.slice(p.length).trim(); break; }
}
// Remove conectores e palavras muito curtas
const palavras = t.split(/\s+/).filter(w => w.length > 3 && !["para", "com", "sem", "como", "dos", "das", "que", "não", "nao", "melhorada", "melhorado", "prejudicada", "prejudicado", "adulto", "criança", "neonatal", "idoso", "lactente", "feminino", "masculino"].includes(w));
return palavras.slice(0, 4).join(" "); // até 4 palavras-chave como tema
}

for (const d of pontuados) {
const tema = extrairTema(d.diagnostico);
if (!temasUsados.has(tema) && !temasUsados.has(d.codigo)) {
temasUsados.add(tema);
temasUsados.add(d.codigo);
topDiversos.push(d);
}
if (topDiversos.length >= 6) break;
}

if (topDiversos.length > 0) {
lista.innerHTML = "";
topDiversos.forEach((d) => {
lista.innerHTML += `
<li class="nanda-item flex items-start gap-3">
<span class="bg-blue-100 text-blue-800 text-[10px] font-black px-2 py-1 rounded shadow-sm mt-0.5">${d.codigo}</span>
<div>
<h5 class="text-[13px] font-bold text-slate-800 leading-tight mb-1">${d.diagnostico}</h5>
<p class="text-[11px] text-slate-500 leading-snug m-0">${d.definicao}</p>
</div>
</li>
`;
});
} else {
lista.innerHTML = '<li class="text-xs text-slate-500 text-center py-4">Brak krytycznej diagnozy pierwotnej związanej z bieżącymi wyborami.</li>';
}
} catch (e) {
lista.innerHTML = '<li class="text-xs text-red-500 text-center py-4">Baza danych NANDA tymczasowo niedostępna.</li>';
}
}

function limpar() {
ITENS_SILVERMAN.forEach((item) => {
document.getElementById(item.id).value = "";
document.getElementById(`card_${item.id}`).classList.remove("error");

const badge = document.getElementById(`badge_${item.id}`);
const bar = document.getElementById(`bar_${item.id}`);
badge.textContent = `--/2`;
bar.style.width = `0%`;
